def count_substring(s, sub):
    count = 0
    for i in range(len(s) - len(sub) + 1):
        if s[i:i + len(sub)] == sub:
            count += 1
    return count

def rotate_list(lst, k):
    if not lst:
        return []
    k = k % len(lst)
    return lst[-k:] + lst[:-k]

def interleave(a, b):
    out = []
    for x, y in zip(a, b):
        out.append(x)
        out.append(y)
    return out

def last_index(lst, x):
    result = -1
    for i, v in enumerate(lst):
        if v == x:
            result = i
    return result

def safe_get(lst, i, default=None):
    if 0 <= i < len(lst):
        return lst[i]
    return default

def drop_while(lst, pred):
    for i, v in enumerate(lst):
        if not pred(v):
            return lst[i:]
    return []

def first_negative(nums):
    for n in nums:
        if n < 0:
            return n
    return None

def merge_with_add(a, b):
    out = dict(a)
    for k, v in b.items():
        out[k] = out.get(k, 0) + v
    return out

def count_by(items, key):
    counts = {}
    for item in items:
        k = key(item)
        counts[k] = counts.get(k, 0) + 1
    return counts

def is_prime_num(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def gcd_of(a, b):
    while b:
        a, b = b, a % b
    return a

def digit_product(n):
    result = 1
    for ch in str(n):
        result *= int(ch)
    return result

def int_sqrt(n):
    if n < 2:
        return n
    lo, hi = 1, n // 2
    while lo <= hi:
        mid = (lo + hi) // 2
        if mid * mid <= n:
            lo = mid + 1
        else:
            hi = mid - 1
    return hi

def fizzbuzz_at(n):
    if n % 15 == 0:
        return 'FizzBuzz'
    if n % 3 == 0:
        return 'Fizz'
    if n % 5 == 0:
        return 'Buzz'
    return str(n)

