def while_countdown(n):
    out = []
    while n >= 1:
        out.append(n)
        n -= 1
    return out

def until_zero(n):
    steps = 0
    while n > 0:
        n //= 2
        steps += 1
    return steps

def flatten_one_level(items):
    out = []
    for item in items:
        if isinstance(item, list):
            out.extend(item)
        else:
            out.append(item)
    return out

def categorize_score(score):
